import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { join } from 'node:path';
import { describe, it } from 'node:test';
import { fileURLToPath } from 'node:url';
import { formatPromptSnapshot } from '../src/format-prompt-snapshot.js';

const ORACLE_FOLDER = fileURLToPath(new URL('./fixtures/prompt-snapshot/', import.meta.url));
const HEAD = [
  '',
  'Generated by `dwfb snapshot`. Do not edit this file by hand.',
  'Each entry below is one distinct prompt that a role receives, with the scenario that first sent it.',
  '',
  '| Role | Variant | Schema | Characters | First scenario |',
  '|---|---|---|---|---|',
];

/**
 * @param {Partial<import('../src/build-prompt-snapshot.js').PromptVariant>} fields
 * @returns {import('../src/build-prompt-snapshot.js').PromptVariant}
 */
function createVariant(fields) {
  return { role: 'work', number: 1, schemaNumber: 1, characters: 4, scenario: 's', label: 'work', prompt: 'Run.', schema: null, ...fields };
}

/**
 * @param {import('../src/build-prompt-snapshot.js').PromptVariant} variant
 * @returns {string[]} The lines of the document of one variant.
 */
function formatLines(variant) {
  return formatPromptSnapshot('t', [variant]).split('\n');
}

describe('formatPromptSnapshot', () => {
  it('gives the oracle document of the reference generator for the variants of the oracle script', async () => {
    const { variants } = JSON.parse(await readFile(join(ORACLE_FOLDER, 'review.snapshot.json'), 'utf8'));

    assert.equal(formatPromptSnapshot('review', variants), await readFile(join(ORACLE_FOLDER, 'review.prompts.md'), 'utf8'));
  });

  it('writes one row and one section per variant, with a blank line between sections and one line end at the end', () => {
    const document = formatPromptSnapshot('t', [createVariant({}), createVariant({ number: 2, prompt: 'Run again.', characters: 10 })]);

    assert.equal(document, [
      '# t prompt snapshot',
      ...HEAD,
      '| work | 1 | 1 | 4 | s |',
      '| work | 2 | 1 | 10 | s |',
      '',
      '## work, variant 1, schema 1',
      '',
      '`work` in the scenario "s"',
      '',
      '~~~~text',
      'Run.',
      '~~~~',
      '',
      '~~~~json',
      'null',
      '~~~~',
      '',
      '## work, variant 2, schema 1',
      '',
      '`work` in the scenario "s"',
      '',
      '~~~~text',
      'Run again.',
      '~~~~',
      '',
      '~~~~json',
      'null',
      '~~~~',
      '',
    ].join('\n'));
  });

  it('writes the head and the table head alone for no variant', () => {
    assert.equal(formatPromptSnapshot('t', []), `${['# t prompt snapshot', ...HEAD].join('\n')}\n`);
  });

  it('opens a fence one longer than the longest run of ~ in its text, and 4 at least', () => {
    const lines = formatLines(createVariant({ prompt: 'a ~~~~~~ b\n~~~~~~', schema: { note: '~~~~~' } }));

    assert.deepEqual(lines.slice(13, 17), ['~~~~~~~text', 'a ~~~~~~ b', '~~~~~~', '~~~~~~~']);
    assert.deepEqual(lines.slice(18, 20), ['~~~~~~json', '{']);
    assert.equal(lines.at(-2), '~~~~~~');
  });

  it('closes the code span of a label with a backtick run one longer than the longest in the label, with a space inside each end for a backtick at an end', () => {
    assert.equal(formatLines(createVariant({ label: 'work `a`' }))[11], '`` work `a` `` in the scenario "s"');
    assert.equal(formatLines(createVariant({ label: 'work ``a`` b' }))[11], '```work ``a`` b``` in the scenario "s"');
    assert.equal(formatLines(createVariant({ label: '`work' }))[11], '`` `work `` in the scenario "s"');
  });

  it('adds a space inside each end of the code span of a label with a space at both ends, and not for one of spaces alone', () => {
    assert.equal(formatLines(createVariant({ label: ' work ' }))[11], '`  work  ` in the scenario "s"');
    assert.equal(formatLines(createVariant({ label: ' work' }))[11], '` work` in the scenario "s"');
    assert.equal(formatLines(createVariant({ label: '  ' }))[11], '`  ` in the scenario "s"');
  });

  it('writes a call with no label and a call with the empty label as such', () => {
    assert.equal(formatLines(createVariant({ label: null }))[11], 'A call with no label in the scenario "s"');
    assert.equal(formatLines(createVariant({ label: '' }))[11], 'A call with the empty label in the scenario "s"');
  });

  it('writes a role and a scenario name as a table cell, and a hidden character of a role, a label or a scenario name as its escape', () => {
    const lines = formatLines(createVariant({ role: 'a|b\u0007', label: 'work\nnext', scenario: 'one *two*\n' }));

    assert.equal(lines[7], '| a\\|b\\\\u{0007} | 1 | 1 | 4 | one \\*two\\*\\\\u{000A} |');
    assert.equal(lines[9], '## a\\|b\\\\u{0007}, variant 1, schema 1');
    assert.equal(lines[11], '`work\\u{000A}next` in the scenario "one \\*two\\*\\\\u{000A}"');
  });

  it('writes the prompt and the schema text as they are', () => {
    const lines = formatLines(createVariant({ prompt: 'a | <b> *c*', schema: { type: 'string' } }));

    assert.deepEqual(lines.slice(13, 16), ['~~~~text', 'a | <b> *c*', '~~~~']);
    assert.deepEqual(lines.slice(17, 22), ['~~~~json', '{', '  "type": "string"', '}', '~~~~']);
  });
});
